    spaces = generate_spaces(n - floor - 1)
    slashes = generate_slashes(2 * floor + 1)
    return f"{spaces}{slashes}\\{spaces}\n"

def generate_base(n):
    return generate_spaces(n - 1) + generate_slashes(2 * n + 1) + '\n'

