    current_time = start_time + timedelta(minutes=minutes)
    return current_time.strftime('%A')

def get_time_in_24hr_format(minutes):
    start_time = datetime(2023, 1, 1)  # Start from a fixed date, e.g., January 1, 2023
    current_time = start_time + timedelta(minutes=minutes)
    return current_time.strftime('%H:%M')

