    cats = ['L', 'M', 'R']
    for i in range(len(cats)):
        for j in range(i + 1, len(cats)):
            if positions[cats[i]] and positions[cats[j]]:
                for pos1 in positions[cats[i]]:
                    for pos2 in positions[cats[j]]:
                        distance = calculate_distance(pos1, pos2)
                        if distance < min_distance:
                            return False
    return True

